random_tests.generator:
const count = 6 + Math.floor(Math.random() * 10);
const tasks = Array.from({ length: count }, (_, index) => ({
  id: `task-${String(index).padStart(2, '0')}`,
  priority: 1 + Math.floor(Math.random() * 10),
  dependencies: []
}));
for (let index = 1; index < count; index++) {
  for (let previous = 0; previous < index; previous++) {
    if (Math.random() < 0.18) tasks[index].dependencies.push(tasks[previous].id);
  }
}
for (let index = tasks.length - 1; index > 0; index--) {
  const swap = Math.floor(Math.random() * (index + 1));
  [tasks[index], tasks[swap]] = [tasks[swap], tasks[index]];
}
return [tasks];

random_tests.oracle:
const tasks = args[0];
const byId = new Map(tasks.map(task => [task.id, task]));
const degree = new Map(tasks.map(task => [task.id, task.dependencies.length]));
const next = new Map(tasks.map(task => [task.id, []]));
for (const task of tasks) for (const dependency of task.dependencies) next.get(dependency).push(task.id);
const available = tasks.filter(task => degree.get(task.id) === 0);
const result = [];
while (available.length) {
  available.sort((a, b) => b.priority - a.priority || a.id.localeCompare(b.id));
  const current = available.shift();
  result.push(current.id);
  for (const id of next.get(current.id)) {
    degree.set(id, degree.get(id) - 1);
    if (degree.get(id) === 0) available.push(byId.get(id));
  }
}
return result.length === tasks.length ? result : [];
